{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C20"],
      "claim": "Delpazolid, the closest analogue (Morgan 0.4861), has absolute oral bioavailability close to 100% in humans and shares the same oxazolidinone-CH2OH and fluorophenyl core with the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C48"],
      "claim": "Linezolid, a closely related oxazolidinone, has essentially 100% absolute oral bioavailability in humans, supporting high oral absorption for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Contezolid, another oxazolidinone, shows F = 0.64 in healthy subjects, which is above the 20% threshold and supports adequate oral bioavailability for the class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a linezolid analogue with a thiomorpholine, has low absolute bioavailability of 10.1%, but its structural difference from the query's tetrazole-pyridine linker limits transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is structurally closest to delpazolid and linezolid, both with near-complete oral bioavailability, and the shared oxazolidinone-fluorophenyl core strongly supports F ≥ 20%. The added tetrazole-pyridine linker introduces polarity and ionization uncertainty, but the threshold is low and the closest experimental evidence points to high bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the exact query molecule.",
    "The effect of the tetrazole and pyridine linker on permeability, solubility, and first-pass metabolism is not directly covered by the retrieved analogues.",
    "Human pharmacokinetic data for this specific scaffold are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

